INSERT INTO `customer_satisfaction` (`id`, `user_id`, `related_order_id`, `related_companion_id`, `satisfaction_score`, `comment`, `feedback_tags`, `is_anonymous`, `service_type`, `reply_content`, `replied_by`, `replied_at`, `created_at`) VALUES
(1, 1, 1, 1, 5, '非常棒的服务！陪玩师技术一流，态度也很好，下次还来！', '技术好,态度好,准时', 0, 'ACCOMPANY', '感谢您的认可，我们会继续努力提供优质服务！', 3, '2026-05-02 10:00:00', '2026-05-01 20:00:00'),
(2, 2, 2, 3, 4, '服务不错，就是价格稍微贵了点，希望能有更多优惠活动', '价格,建议,优惠', 0, 'ACCOMPANY', '感谢您的反馈，我们近期会有优惠活动推出，敬请关注', 3, '2026-04-21 10:00:00', '2026-04-20 22:00:00'),
(3, 3, 3, 5, 2, '体验不太好，陪玩师迟到半小时，而且技术不如预期', '迟到,技术差,不满', 1, 'TEACHING', '非常抱歉给您带来不好的体验，我们已对该陪玩师进行警告处理，并为您申请补偿', 4, '2026-03-16 09:00:00', '2026-03-15 17:00:00'),
(4, 5, 4, 2, 5, '每次都找这位陪玩师，从来没让我失望过，强烈推荐！', '推荐,技术好,老客户', 0, 'ACCOMPANY', '感谢您一直以来的支持，我们将继续提升服务质量！', 3, '2026-04-16 10:00:00', '2026-04-15 21:00:00'),
(5, 6, 5, 4, 4, '整体满意，就是沟通上有些小问题，希望改进', '沟通,改进,满意', 0, 'ACCOMPANY', '感谢您的建议，我们会加强陪玩师的沟通培训', 4, '2026-04-11 10:00:00', '2026-04-10 22:00:00'),
(6, 7, 6, 1, 5, '顶尖陪玩师就是不一样，实力碾压，学到了很多技巧', '技术好,教学,推荐', 0, 'TEACHING', '很高兴能帮到您，祝您游戏愉快！', 3, '2026-03-21 10:00:00', '2026-03-20 20:00:00'),
(7, 9, 7, 6, 1, '太差了！陪玩师一直催单，态度恶劣，要求退款！', '态度差,退款,投诉', 0, 'ACCOMPANY', '非常抱歉给您带来极差的体验，我们已经对该陪玩师进行处理，订单已退款', 4, '2026-03-25 10:00:00', '2026-03-24 23:00:00'),
(8, 10, 8, 2, 4, '教学内容不错，但感觉时间不太够用，希望能延长一下', '教学,时间,建议', 0, 'TEACHING', '感谢您的建议，我们会考虑调整教学时长方案', 3, '2026-04-26 10:00:00', '2026-04-25 12:00:00'),
(9, 14, 9, 3, 5, '套餐很划算，性价比高，服务时长也很充足', '套餐,划算,推荐', 0, 'PACKAGE', '感谢您的认可，我们会推出更多优惠套餐！', 3, '2026-05-03 10:00:00', '2026-05-02 14:00:00'),
(10, 16, 10, 4, 5, '老客户了，服务始终如一的好，值得信赖', '老客户,信赖,推荐', 0, 'ACCOMPANY', '感谢您长期的信任与支持，我们将继续努力！', 4, '2026-05-06 10:00:00', '2026-05-05 10:00:00');
