INSERT INTO `club_config` (`id`, `club_name`, `club_logo`, `main_games`, `service_slogan`, `welcome_message`, `contact_info`, `price_level_two`, `price_level_one`, `price_top`, `price_star`, `club_features`, `custom_level_names`, `service_promise`, `refund_policy`, `member_discount`, `recharge_bonus`, `custom_welcome_template`, `ai_personality`, `created_at`) VALUES
(1, '三角洲精英俱乐部', 'https://cdn.delta.com/clubs/elite_logo.png', '三角洲行动,CSGO,APEX', '专业陪玩，带你起飞！', '欢迎加入三角洲精英俱乐部！我们提供最专业的陪玩服务，助你成为游戏中的王者！', '客服电话: 400-888-0001', 150.00, 300.00, 500.00, 1000.00, '拥有三角洲行动TOP100排名选手,专业教练团队,7x24小时服务', '{"LEVEL_TWO":"精英", "LEVEL_ONE":"大师", "TOP":"王者", "STAR":"传奇"}', '不满意全额退款，迟到双倍赔偿', '服务开始前可全额退款，服务开始后按比例退款', 0.90, '充值1000送100，充值5000送800', '亲爱的{昵称}，欢迎加入三角洲精英俱乐部！', '专业热情', '2026-01-01 00:00:00'),
(2, '夜猫子陪玩社', 'https://cdn.delta.com/clubs/night_logo.png', '三角洲行动,绝地求生,战地', '深夜不孤单，陪你战到天亮', '欢迎来到夜猫子陪玩社！深夜档专属陪玩，让你不再孤独上分！', '客服电话: 400-888-0002', 100.00, 200.00, 400.00, 800.00, '深夜专属服务(22:00-06:00),高颜值陪玩师团队,语音/视频陪玩', '{"LEVEL_TWO":"夜莺", "LEVEL_ONE":"夜鹰", "TOP":"夜神", "STAR":"夜皇"}', '深夜服务保障，不满意免费重来', '服务开始前可全额退款', 0.85, '首单8折，推荐好友双方各得100元代金券', '嘿{昵称}，夜猫子们都在等你哦！', '活泼亲切', '2026-01-15 00:00:00'),
(3, '新手成长学院', 'https://cdn.delta.com/clubs/academy_logo.png', '三角洲行动,使命召唤,彩虹六号', '从菜鸟到大神，我们一路相伴', '欢迎加入新手成长学院！零基础也不用怕，我们的专业教练带你从零开始，快速成长！', '客服电话: 400-888-0003', 80.00, 200.00, 350.00, 600.00, '新手专属教学体系,技能评估报告,成长路线规划,一对一指导', '{"LEVEL_TWO":"助教", "LEVEL_ONE":"讲师", "TOP":"教授", "STAR":"院士"}', '学不会免费重教，包教包会', '课程开始前可全额退款', 0.80, '学生认证享8折，首次注册送免费体验课', '{昵称}同学，准备好开启你的成长之旅了吗？', '耐心温和', '2026-02-01 00:00:00');
