INSERT INTO `faq_items` (`id`, `category`, `question`, `answer`, `sort_order`, `enabled`, `created_at`) VALUES
(1, '服务流程', '如何预约陪玩服务？', '您可以通过以下方式预约：1.在聊天窗口直接告诉AI客服您的需求 2.AI会自动匹配适合的陪玩师 3.确认时间和价格后下单支付 4.陪玩师准时上线为您服务', 1, 1, '2026-01-01 00:00:00'),
(2, '价格说明', '陪玩师怎么收费？', '陪玩师按等级收费：二品150元/小时、一品300元/小时、顶尖500元/小时、明星1000元/小时。新用户首单享8折，会员更有多重优惠。', 2, 1, '2026-01-01 00:00:00'),
(3, '支付方式', '支持哪些支付方式？', '我们支持微信支付、支付宝、银行卡转账等多种支付方式。支付完成后系统会自动确认并安排服务。', 3, 1, '2026-01-01 00:00:00'),
(4, '退款政策', '如果服务不满意可以退款吗？', '当然可以！我们的退款政策：1.服务开始前可全额退款 2.服务中不满意可按比例退款 3.陪玩师迟到双倍赔偿 4.技术不达标免费重来', 4, 1, '2026-01-15 00:00:00'),
(5, '会员权益', '会员有什么特权？', '会员等级越高享受越多权益：青铜会员享9折+优先匹配、白银会员享8.5折+专属客服、黄金会员享8折+免费升等、铂金会员享7.5折+私人订制、钻石会员享7折+全部特权', 5, 1, '2026-02-01 00:00:00'),
(6, '技术支持', '如果遇到技术问题怎么办？', '您可以：1.直接联系在线客服 2.拨打客服电话400-888-0001 3.提交工单，我们会在2小时内响应处理', 6, 1, '2026-02-15 00:00:00'),
(7, '账号管理', '如何修改个人信息？', '请登录系统后进入「个人中心」→「账号设置」即可修改昵称、头像、联系方式等信息。如需修改实名认证信息请联系客服。', 7, 1, '2026-03-01 00:00:00'),
(8, '隐私安全', '个人数据安全吗？', '我们非常重视您的隐私安全！所有数据采用银行级加密存储，严格遵守数据保护法规，未经授权不会向第三方透露您的个人信息。', 8, 1, '2026-03-15 00:00:00'),
(9, '平台支持', '支持哪些平台？', '目前我们支持微信、KOOK、YY等多个主流社交平台，您可以在以上平台直接使用我们的服务。更多平台正在接入中。', 9, 1, '2026-04-01 00:00:00'),
(10, '合作咨询', '如何成为陪玩师？', '如果您有意向成为陪玩师，请发送简历和游戏战绩截图至 hr@delta.com，我们的HR团队会在3个工作日内与您联系。', 10, 1, '2026-04-15 00:00:00');
