INSERT INTO `replies` (`id`, `trigger_type`, `trigger_key`, `content`, `enabled`, `created_at`) VALUES
(1, 'keyword', '下单', '好的！请问您想预约什么时间段的陪玩服务呢？我们可以为您匹配最适合的陪玩师。', 1, '2026-01-15 00:00:00'),
(2, 'keyword', '预约', '很高兴为您服务！请告诉我您想要的游戏类型、时段和陪玩师等级，我来为您安排。', 1, '2026-01-15 00:00:00'),
(3, 'keyword', '价格', '我们的服务价格根据等级不同：二品150元/小时、一品300元/小时、顶尖500元/小时、明星1000元/小时。新用户首单享8折哦！', 1, '2026-02-01 00:00:00'),
(4, 'welcome', 'welcome', '欢迎加入{俱乐部名称}！我是您的AI助手，随时为您解答问题、预约服务。请问有什么可以帮您的？', 1, '2026-01-01 00:00:00'),
(5, 'default', 'default', '很抱歉，我暂时无法完全理解您的问题。正在为您转接人工客服，请稍等～', 1, '2026-01-01 00:00:00'),
(6, 'keyword', '帮助', '我可以帮您：1.查询价格 2.预约陪玩 3.了解套餐 4.转人工服务 5.查询订单。请告诉我您需要什么帮助？', 1, '2026-03-01 00:00:00');
