(1, 3, 5, 3, '2026-03-16 14:00:00', 'SERVICE', 'MEDIUM', 55, NULL, '陪玩师周星星迟到15分钟，未提前通知客户', 'https://cdn.delta.com/evidence/qc001.png', '警告处分，扣除当月绩效50元', 'RESOLVED', 4, '已警告并扣款', '2026-03-16 14:00:00'),
